#!/usr/bin/env python3
"""EPIC protocol laboratory.

Reads UTF-8 JSON Lines on stdin, writes exactly one JSON object per input
line on stdout.  Implements three operations:

  * ``replay`` -- bounded star switch with cumulative acknowledgements.
  * ``audit``  -- observational safety / fair termination of a finite graph.
  * ``export`` -- lossless TLA+ ``ModelData`` module export.

Standard library only; no arguments, files, network or subprocesses.
"""

import json
import math
import re
import sys

# --------------------------------------------------------------------------
# limits
# --------------------------------------------------------------------------

MAX_LINE_BYTES = 32 * 1024 * 1024
MAX_PENDING_PACKETS = 2048
MAX_TOTAL_PACKETS = 200000
MAX_EVENTS = 20000
MAX_PACKET_ID = 200000

NAME_RE = re.compile(r"\A[A-Za-z][A-Za-z0-9_]*\Z")

INPUT_LO = -1000000000
INPUT_HI = 1000000000
SNAP_LO = -(1 << 60)
SNAP_HI = (1 << 60)


class SchemaError(Exception):
    """Malformed request (structure / types / duplicates)."""


class LimitError(Exception):
    """Request violates a numeric range, string length or size bound."""


def is_int(x):
    return type(x) is int


# --------------------------------------------------------------------------
# JSON parsing (strict)
# --------------------------------------------------------------------------


def _object_pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError("duplicate object key")
        out[key] = value
    return out


def _parse_constant(_token):
    raise ValueError("non-finite number")


def _parse_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("non-finite number")
    return value


def parse_json(text):
    return json.loads(
        text,
        object_pairs_hook=_object_pairs,
        parse_constant=_parse_constant,
        parse_float=_parse_float,
    )


# --------------------------------------------------------------------------
# shared validation helpers
# --------------------------------------------------------------------------


def require_keys(obj, keys):
    if not isinstance(obj, dict):
        raise SchemaError
    if set(obj.keys()) != set(keys):
        raise SchemaError


def check_name(name):
    if not isinstance(name, str):
        raise SchemaError
    if len(name) > 64:
        raise LimitError
    if not NAME_RE.match(name):
        raise SchemaError


def validate_inputs(obj):
    if "inputs" not in obj:
        raise SchemaError
    inputs = obj["inputs"]
    if not isinstance(inputs, list):
        raise SchemaError
    p_count = len(inputs)
    if p_count < 1 or p_count > 8:
        raise LimitError
    r_count = -1
    d_count = 0
    for rank in inputs:
        if not isinstance(rank, list):
            raise SchemaError
        if r_count < 0:
            r_count = len(rank)
            if r_count > 128:
                raise LimitError
            if r_count > 0:
                first = rank[0]
                if not isinstance(first, list):
                    raise SchemaError
                d_count = len(first)
                if d_count > 32:
                    raise LimitError
        elif len(rank) != r_count:
            raise SchemaError
        for vec in rank:
            if not isinstance(vec, list):
                raise SchemaError
            if len(vec) != d_count:
                raise SchemaError
            for value in vec:
                if not is_int(value):
                    raise SchemaError
                if value < INPUT_LO or value > INPUT_HI:
                    raise LimitError
    if r_count < 0:
        r_count = 0
    return inputs, p_count, r_count, d_count


# --------------------------------------------------------------------------
# replay
# --------------------------------------------------------------------------


def validate_replay_events(events, p_count, r_count):
    if not isinstance(events, list):
        raise SchemaError
    if len(events) > MAX_EVENTS:
        raise LimitError
    for event in events:
        if not isinstance(event, list) or not event:
            raise SchemaError
        kind = event[0]
        if not isinstance(kind, str):
            raise SchemaError
        if kind == "send":
            if len(event) != 3:
                raise SchemaError
            rank = event[1]
            seq = event[2]
            if not is_int(rank) or not is_int(seq):
                raise SchemaError
            if rank < 0 or rank >= p_count:
                raise LimitError
            if seq < 0 or seq >= r_count:
                raise LimitError
        elif kind == "retry":
            if len(event) != 2:
                raise SchemaError
            rank = event[1]
            if not is_int(rank):
                raise SchemaError
            if rank < 0 or rank >= p_count:
                raise LimitError
        elif kind in ("deliver", "drop", "duplicate"):
            if len(event) != 2:
                raise SchemaError
            pid = event[1]
            if not is_int(pid):
                raise SchemaError
            if pid < 0 or pid > MAX_PACKET_ID:
                raise LimitError
        else:
            raise SchemaError


def run_replay(inputs, p_count, r_count, d_count, n_slots, window, events):
    sent = [0] * p_count
    received = [[] for _ in range(p_count)]
    floor = 0
    up_next = [0] * p_count
    acked = [0] * p_count
    buffer = [None] * n_slots
    packets = {}
    next_id = 0
    total_created = 0
    event_log = []

    def create(kind, rank, seq, value):
        nonlocal next_id, total_created
        pid = next_id
        next_id += 1
        total_created += 1
        packets[pid] = {
            "id": pid,
            "kind": kind,
            "rank": rank,
            "seq": seq,
            "value": value,
        }
        if total_created > MAX_TOTAL_PACKETS or len(packets) > MAX_PENDING_PACKETS:
            raise LimitError
        return pid

    for event in events:
        kind = event[0]
        created = []
        if kind == "send":
            rank = event[1]
            seq = event[2]
            if sent[rank] <= seq < min(r_count, sent[rank] + window):
                created.append(create("up", rank, seq, list(inputs[rank][seq])))
                status = "ok"
            else:
                status = "disabled"
        elif kind == "retry":
            rank = event[1]
            entries = []
            for entry in buffer:
                if entry is None:
                    continue
                if len(entry["ranks"]) == p_count and entry["seq"] >= acked[rank]:
                    entries.append(entry)
            entries.sort(key=lambda item: item["seq"])
            for entry in entries:
                created.append(
                    create("down", rank, entry["seq"], list(entry["sum"]))
                )
            status = "ok"
        elif kind == "drop":
            pid = event[1]
            if pid in packets:
                del packets[pid]
                status = "ok"
            else:
                status = "missing"
        elif kind == "duplicate":
            pid = event[1]
            if pid in packets:
                packet = packets[pid]
                value = packet["value"]
                if value is not None:
                    value = list(value)
                created.append(
                    create(packet["kind"], packet["rank"], packet["seq"], value)
                )
                status = "ok"
            else:
                status = "missing"
        else:  # deliver
            pid = event[1]
            if pid not in packets:
                status = "missing"
            else:
                packet = packets.pop(pid)
                pkind = packet["kind"]
                rank = packet["rank"]
                seq = packet["seq"]
                value = packet["value"]
                if pkind == "up":
                    if floor <= seq < floor + n_slots:
                        index = seq % n_slots
                        entry = buffer[index]
                        if entry is None or entry["seq"] != seq:
                            entry = {"seq": seq, "ranks": set(), "sum": [0] * d_count}
                            buffer[index] = entry
                        was_full = len(entry["ranks"]) == p_count
                        if rank not in entry["ranks"]:
                            entry["ranks"].add(rank)
                            if d_count:
                                entry["sum"] = [
                                    a + b for a, b in zip(entry["sum"], value)
                                ]
                        now_full = len(entry["ranks"]) == p_count
                        cursor = up_next[rank]
                        while True:
                            other = buffer[cursor % n_slots]
                            if (
                                other is None
                                or other["seq"] != cursor
                                or rank not in other["ranks"]
                            ):
                                break
                            cursor += 1
                        up_next[rank] = cursor
                        created.append(create("uack", rank, cursor, None))
                        if now_full and not was_full:
                            for target in range(p_count):
                                created.append(
                                    create("down", target, seq, list(entry["sum"]))
                                )
                    else:
                        created.append(create("uack", rank, up_next[rank], None))
                elif pkind == "uack":
                    if seq > sent[rank]:
                        sent[rank] = seq
                elif pkind == "down":
                    if seq == len(received[rank]):
                        received[rank].append(list(value))
                    created.append(create("dack", rank, len(received[rank]), None))
                else:  # dack
                    if seq > acked[rank]:
                        acked[rank] = seq
                    new_floor = min(acked)
                    floor = new_floor
                    for index, entry in enumerate(buffer):
                        if entry is not None and entry["seq"] < new_floor:
                            buffer[index] = None
                status = "ok"
        event_log.append({"status": status, "created": created})

    hosts = [
        {"sent": sent[rank], "received": received[rank]} for rank in range(p_count)
    ]
    slots_out = []
    for entry in buffer:
        if entry is not None:
            slots_out.append(
                {
                    "seq": entry["seq"],
                    "ranks": sorted(entry["ranks"]),
                    "sum": list(entry["sum"]),
                }
            )
    slots_out.sort(key=lambda item: item["seq"])
    packet_list = [packets[pid] for pid in sorted(packets)]
    return {
        "hosts": hosts,
        "floor": floor,
        "slots": slots_out,
        "packets": packet_list,
        "events": event_log,
    }


def handle_replay(obj):
    require_keys(obj, ("op", "inputs", "slots", "window", "events"))
    inputs, p_count, r_count, d_count = validate_inputs(obj)
    n_slots = obj["slots"]
    if not is_int(n_slots):
        raise SchemaError
    if n_slots < 1 or n_slots > 16:
        raise LimitError
    window = obj["window"]
    if not is_int(window):
        raise SchemaError
    if window < 1 or window > n_slots:
        raise LimitError
    events = obj["events"]
    validate_replay_events(events, p_count, r_count)
    return run_replay(
        inputs, p_count, r_count, d_count, n_slots, window, events
    )
