def validate_states(states, p_count, r_count, d_count):
    if not isinstance(states, list):
        raise SchemaError
    if len(states) < 1 or len(states) > 12000:
        raise LimitError
    for state in states:
        if not isinstance(state, dict):
            raise SchemaError
        if set(state.keys()) != {"delivered", "slots"}:
            raise SchemaError
        delivered = state["delivered"]
        if not isinstance(delivered, list):
            raise SchemaError
        if len(delivered) != p_count:
            raise SchemaError
        for rank in delivered:
            if not isinstance(rank, list):
                raise SchemaError
            if len(rank) > r_count:
                raise LimitError
            for vec in rank:
                if not isinstance(vec, list):
                    raise SchemaError
                if len(vec) != d_count:
                    raise SchemaError
                for value in vec:
                    if not is_int(value):
                        raise SchemaError
                    if value < SNAP_LO or value > SNAP_HI:
                        raise LimitError
        slots = state["slots"]
        if not isinstance(slots, list):
            raise SchemaError
        if len(slots) > 16:
            raise LimitError
        seen_seq = set()
        for slot in slots:
            if not isinstance(slot, dict):
                raise SchemaError
            if set(slot.keys()) != {"seq", "ranks", "sum"}:
                raise SchemaError
            seq = slot["seq"]
            if not is_int(seq):
                raise SchemaError
            if seq < 0 or seq >= r_count:
                raise LimitError
            if seq in seen_seq:
                raise SchemaError
            seen_seq.add(seq)
            ranks = slot["ranks"]
            if not isinstance(ranks, list):
                raise SchemaError
            seen_rank = set()
            for rank in ranks:
                if not is_int(rank):
                    raise SchemaError
                if rank < 0 or rank >= p_count:
                    raise LimitError
                if rank in seen_rank:
                    raise SchemaError
                seen_rank.add(rank)
            total = slot["sum"]
            if not isinstance(total, list):
                raise SchemaError
            if len(total) != d_count:
                raise SchemaError
            for value in total:
                if not is_int(value):
                    raise SchemaError
                if value < SNAP_LO or value > SNAP_HI:
                    raise LimitError


def validate_graph(obj):
    require_keys(obj, ("op", "inputs", "states", "edges", "start", "fairness"))
    inputs, p_count, r_count, d_count = validate_inputs(obj)
    states = obj["states"]
    validate_states(states, p_count, r_count, d_count)
    n_states = len(states)
    edges = obj["edges"]
    if not isinstance(edges, list):
        raise SchemaError
    if len(edges) > 60000:
        raise LimitError
    seen = set()
    for edge in edges:
        if not isinstance(edge, list) or len(edge) != 3:
            raise SchemaError
        source = edge[0]
        name = edge[1]
        target = edge[2]
        if not is_int(source) or not is_int(target):
            raise SchemaError
        if source < 0 or source >= n_states:
            raise LimitError
        if target < 0 or target >= n_states:
            raise LimitError
        check_name(name)
        key = (source, name, target)
        if key in seen:
            raise SchemaError
        seen.add(key)
    start = obj["start"]
    if not is_int(start):
        raise SchemaError
    if start < 0 or start >= n_states:
        raise LimitError
    fairness = obj["fairness"]
    if not isinstance(fairness, list):
        raise SchemaError
    if len(fairness) > 16:
        raise LimitError
    fair_names = set()
    for item in fairness:
        if not isinstance(item, dict):
            raise SchemaError
        if set(item.keys()) != {"action", "mode"}:
            raise SchemaError
        name = item["action"]
        mode = item["mode"]
        check_name(name)
        if mode != "weak" and mode != "strong":
            raise SchemaError
        if name in fair_names:
            raise SchemaError
        fair_names.add(name)
    all_names = set(fair_names)
    for edge in edges:
        all_names.add(edge[1])
    if len(all_names) > 64:
        raise LimitError
    return inputs, p_count, r_count, d_count, n_states


# --------------------------------------------------------------------------
# predicates
# --------------------------------------------------------------------------


def compute_predicates(inputs, p_count, r_count, d_count, states):
    """Return (safe, done) boolean lists, one entry per state."""
    grid = [
        [list(inputs[rank][seq]) for seq in range(r_count)]
        for rank in range(p_count)
    ]
    expected = []
    for seq in range(r_count):
        if d_count == 0:
            expected.append([])
            continue
        acc = [0] * d_count
        for rank in range(p_count):
            vec = grid[rank][seq]
            for i in range(d_count):
                acc[i] += vec[i]
        expected.append(acc)
    zero = [0] * d_count
    safe = []
    done = []
    for state in states:
        delivered = state["delivered"]
        ok = True
        for rank in range(p_count):
            got = delivered[rank]
            if got != expected[: len(got)]:
                ok = False
                break
        if ok:
            for slot in state["slots"]:
                ranks = slot["ranks"]
                seq = slot["seq"]
                if ranks:
                    acc = list(
                        map(sum, zip(*[grid[rank][seq] for rank in ranks]))
                    )
                else:
                    acc = list(zero)
                if acc != slot["sum"]:
                    ok = False
                    break
        safe.append(ok)
        done.append(all(len(delivered[rank]) == r_count for rank in range(p_count)))
    return safe, done
