def path_within(src, dst, adj, comp_of, cid):
    if src == dst:
        return []
    prev = {src: None}
    queue = [src]
    head = 0
    while head < len(queue):
        v = queue[head]; head += 1
        for (eid, w) in adj[v]:
            if comp_of.get(w) != cid:
                continue
            if w in prev:
                continue
            prev[w] = (v, eid)
            if w == dst:
                path = []
                cur = w
                while True:
                    pv, pe = prev[cur]
                    path.append(pe)
                    if pv is None:
                        break
                    cur = pv
                path.reverse()
                return path
            queue.append(w)
    return None
