# --------------------------------------------------------------------------
# graph helpers
# --------------------------------------------------------------------------


def tarjan_scc(nodes, adj):
    """Iterative Tarjan SCC.

    nodes: iterable of node ids, adj: dict node -> list of (edge_id, target).
    Returns (comp_of, comps) where comp_of maps node -> component index and
    comps is a list of lists of nodes.
    """
    index = {}
    low = {}
    on_stack = set()
    stack = []
    comp_of = {}
    comps = []
    counter = 0
    for root in nodes:
        if root in index:
            continue
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        on_stack.add(root)
        work = [(root, iter(adj.get(root, ())))]
        while work:
            v, it = work[-1]
            descended = False
            for _eid, w in it:
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    on_stack.add(w)
                    work.append((w, iter(adj.get(w, ()))))
                    descended = True
                    break
                if w in on_stack and index[w] < low[v]:
                    low[v] = index[w]
            if descended:
                continue
            work.pop()
            if work:
                parent = work[-1][0]
                if low[v] < low[parent]:
                    low[parent] = low[v]
            if low[v] == index[v]:
                group = []
                while True:
                    w = stack.pop()
                    on_stack.discard(w)
                    comp_of[w] = len(comps)
                    group.append(w)
                    if w == v:
                        break
                comps.append(group)
    return comp_of, comps


def build_path(parent, target):
    """Edge ids of the tree path start -> target."""
    path = []
    cur = target
    while True:
        entry = parent.get(cur)
        if entry is None:
            break
        prev, eid = entry
        path.append(eid)
        cur = prev
    path.reverse()
    return path


def path_within(src, dst, adj, comp_of, cid):
    """Shortest path (edge ids) from src to dst inside one component."""
    if src == dst:
        return []
    prev = {src: None}
    queue = [src]
    head = 0
    while head < len(queue):
        v = queue[head]
        head += 1
        for eid, w in adj[v]:
            if comp_of.get(w) != cid:
                continue
            if w in prev:
                continue
            prev[w] = (v, eid)
            if w == dst:
                path = []
                cur = w
                while True:
                    pentry = prev[cur]
                    path.append(pentry[1])
                    if pentry[0] is None:
                        break
                    cur = pentry[0]
                path.reverse()
                return path
            queue.append(w)
    return None


def find_fair_cycle(reach, adj_all, edge_src, edge_tgt, edge_name, enabled, fairness):
    """Search for a fair closed walk inside the reachable non-done subgraph.

    Returns (loop_edge_ids, loop_start_state) or None.
    """
    fair_names = [item["action"] for item in fairness]
    fair_mode = {item["action"]: item["mode"] for item in fairness}
    radj = {}
    for v in reach:
        radj[v] = [(eid, w) for (eid, w) in adj_all[v] if w in reach]
    comp_of, comps = tarjan_scc(reach, radj)
    disabled = {}
    for name in fair_names:
        dis = enabled.get(name)
        if dis:
            disabled[name] = set(reach) - dis
        else:
            disabled[name] = set(reach)
    for cid, nodes in enumerate(comps):
        internal = []
        for v in nodes:
            for eid, w in radj[v]:
                if comp_of[w] == cid:
                    internal.append(eid)
        if not internal:
            continue
        by_label = {}
        for eid in internal:
            by_label.setdefault(edge_name[eid], []).append(eid)
        avail = [nm for nm in fair_names if nm in by_label]
        forced = [nm for nm in fair_names if nm not in by_label]
        nopt = len(avail)
        masks = sorted(range(1 << nopt), key=lambda m: bin(m).count("1"))
        for mask in masks:
            unc = set(forced)
            for i in range(nopt):
                if (mask >> i) & 1:
                    unc.add(avail[i])
            nodeset = set(nodes)
            ok = True
            for nm in unc:
                if fair_mode[nm] == "strong":
                    nodeset &= disabled[nm]
                    if not nodeset:
                        ok = False
                        break
            if not ok:
                continue
            for nm in unc:
                if fair_mode[nm] == "weak" and not (nodeset & disabled[nm]):
                    ok = False
                    break
            if not ok:
                continue
            for nm in fair_names:
                if nm in unc:
                    continue
                found = False
                for eid in by_label[nm]:
                    if edge_src[eid] in nodeset and edge_tgt[eid] in nodeset:
                        found = True
                        break
                if not found:
                    ok = False
                    break
            if not ok:
                continue
            sub_adj = {v: [] for v in nodeset}
            sub_edges = []
            for eid in internal:
                u = edge_src[eid]
                w = edge_tgt[eid]
                if u in nodeset and w in nodeset and edge_name[eid] not in unc:
                    sub_edges.append(eid)
                    sub_adj[u].append((eid, w))
            if not sub_edges:
                continue
            sub_comp, sub_comps = tarjan_scc(nodeset, sub_adj)
            for scid, snodes in enumerate(sub_comps):
                sub_internal = [
                    eid
                    for eid in sub_edges
                    if sub_comp[edge_src[eid]] == scid
                ]
                if not sub_internal:
                    continue
                sub_by_label = {}
                for eid in sub_internal:
                    sub_by_label.setdefault(edge_name[eid], []).append(eid)
                good = True
                for nm in fair_names:
                    if nm in unc:
                        continue
                    if nm not in sub_by_label:
                        good = False
                        break
                if not good:
                    continue
                visits = []
                for nm in unc:
                    if fair_mode[nm] == "weak":
                        candidate = None
                        for s in snodes:
                            if s in disabled[nm]:
                                candidate = s
                                break
                        if candidate is None:
                            good = False
                            break
                        visits.append(candidate)
                if not good:
                    continue
                req_edges = [
                    sub_by_label[nm][0] for nm in fair_names if nm not in unc
                ]
                if req_edges:
                    start_state = edge_src[req_edges[0]]
                else:
                    start_state = snodes[0]
                walk = []
                cur = start_state
                tasks = [("e", eid) for eid in req_edges]
                tasks.extend(("s", st) for st in visits)
                for tkind, tval in tasks:
                    if tkind == "e":
                        seg = path_within(
                            cur, edge_src[tval], sub_adj, sub_comp, scid
                        )
                        if seg is None:
                            good = False
                            break
                        walk.extend(seg)
                        walk.append(tval)
                        cur = edge_tgt[tval]
                    else:
                        seg = path_within(cur, tval, sub_adj, sub_comp, scid)
                        if seg is None:
                            good = False
                            break
                        walk.extend(seg)
                        cur = tval
                if not good:
                    continue
                seg = path_within(cur, start_state, sub_adj, sub_comp, scid)
                if seg is None:
                    continue
                walk.extend(seg)
                return walk, start_state
    return None


# --------------------------------------------------------------------------
# operations
# --------------------------------------------------------------------------


def handle_audit(obj):
