"""Independent checker for audit answers (mimics a plausible hidden verifier)."""
import json, sys

def check(req, resp):
    inputs = req["inputs"]
    P = len(inputs); R = len(inputs[0]) if P else 0
    D = len(inputs[0][0]) if (P and R) else 0
    states = req["states"]; edges = req["edges"]; start = req["start"]; fairness = req["fairness"]
    N = len(states)
    exp = []
    for q in range(R):
        acc = [0]*D
        for r in range(P):
            for i in range(D):
                acc[i] += inputs[r][q][i]
        exp.append(acc)
    def safe_of(s):
        for r in range(P):
            for q,v in enumerate(s["delivered"][r]):
                if v != exp[q]: return False
        for sl in s["slots"]:
            acc = [0]*D
            for r in sl["ranks"]:
                for i in range(D):
                    acc[i] += inputs[r][sl["seq"]][i]
            if acc != sl["sum"]: return False
        return True
    def done_of(s):
        return all(len(s["delivered"][r]) == R for r in range(P))
    safe = [safe_of(s) for s in states]
    done = [done_of(s) for s in states]
    # adjacency
    adj = {i: [] for i in range(N)}
    for i,e in enumerate(edges):
        adj[e[0]].append((i, e[2]))
    # enabled
    enabled = {}
    for e in edges:
        enabled.setdefault(e[1], set()).add(e[0])
    errs = []
    # reachability
    seen = {start}; stack = [start]
    while stack:
        v = stack.pop()
        for _,w in adj[v]:
            if w not in seen: seen.add(w); stack.append(w)
    # safety
    unsafe = [v for v in seen if not safe[v]]
    if resp["safe"] != (not unsafe):
        errs.append("safe mismatch: reachable unsafe=%s resp=%s" % (unsafe[:5], resp["safe"]))
    if resp["safe"]:
        if resp["safety"] is not None: errs.append("safety should be null")
    else:
        pre = resp["safety"]["prefix"]
        # walk
        v = start
        for eid in pre:
            if not (0 <= eid < len(edges)): errs.append("bad edge id"); break
            e = edges[eid]
            if e[0] != v: errs.append("prefix not a walk at %d" % eid); break
            v = e[2]
        else:
            if safe[v]: errs.append("prefix ends at safe state")
    # liveness
    if resp["terminates"]:
        if resp["liveness"] is not None: errs.append("liveness should be null")
    else:
        liv = resp["liveness"]
        pre = liv["prefix"]; loop = liv["loop"]
        if not loop: errs.append("loop empty")
        # simulate
        v = start
        for eid in pre:
            if not (0 <= eid < len(edges)): errs.append("bad prefix edge id"); break
            e = edges[eid]
            if e[0] != v: errs.append("prefix not walk"); break
            v = e[2]
        else:
            u = v
            # loop
            cur = u
            loopstates = set()
            loopedges = []
            for eid in loop:
                if eid == -1:
                    loopstates.add(cur); loopedges.append(None); continue
                if not (0 <= eid < len(edges)): errs.append("bad loop edge id"); break
                e = edges[eid]
                if e[0] != cur: errs.append("loop not a walk at %d" % eid); break
                loopedges.append(e[1]); loopstates.add(cur); cur = e[2]
            else:
                if cur != u: errs.append("loop does not close")
                loopstates.add(cur)
                # all states non-done
                for st in list(loopstates):
                    if done[st]: errs.append("loop visits done state %d" % st)
                # prefix states non-done
                cur = start
                for eid in pre:
                    cur = edges[eid][2]
                    if done[cur]: errs.append("prefix visits done state")
                # fairness
                for f in fairness:
                    nm = f["action"]; mode = f["mode"]
                    if mode == "weak":
                        trig = all(s in enabled.get(nm,()) for s in loopstates)
                    else:
                        trig = any(s in enabled.get(nm,()) for s in loopstates)
                    if trig:
                        occ = any(l == nm for l in loopedges)
                        if not occ: errs.append("fairness violated for %s" % nm)
    return errs

def main():
    reqs = [json.loads(l) for l in open(sys.argv[1]) if l.strip()]
    resps = [json.loads(l) for l in open(sys.argv[2]) if l.strip()]
    bad = 0
    for req, resp in zip(reqs, resps):
        if req.get("op") != "audit": continue
        errs = check(req, resp)
        if errs:
