def dispatch(obj):
    if not isinstance(obj, dict):
        raise SchemaError
    if "op" not in obj or "inputs" not in obj:
        raise SchemaError
    op = obj["op"]
    if not isinstance(op, str):
        raise SchemaError
    if op == "replay":
        return handle_replay(obj)
    if op == "audit":
        return handle_audit(obj)
    if op == "export":
        return handle_export(obj)
    raise SchemaError


def main():
    out = sys.stdout
    for raw in sys.stdin.buffer:
        if raw.endswith(b"\n"):
            raw = raw[:-1]
        if len(raw) > MAX_LINE_BYTES:
            response = {"error": "E_LIMIT"}
        else:
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                response = {"error": "E_JSON"}
            else:
                try:
                    obj = parse_json(text)
                except Exception:
                    response = {"error": "E_JSON"}
                else:
                    try:
                        response = dispatch(obj)
                    except SchemaError:
                        response = {"error": "E_SCHEMA"}
                    except LimitError:
                        response = {"error": "E_LIMIT"}
                    except RecursionError:
                        response = {"error": "E_LIMIT"}
                    except MemoryError:
                        response = {"error": "E_LIMIT"}
        try:
            out.write(json.dumps(response, separators=(",", ":")))
            out.write("\n")
        except BrokenPipeError:
            return
    try:
        out.flush()
    except BrokenPipeError:
        pass


if __name__ == "__main__":
    main()

