def find_fair_cycle(reach, adj_all, edge_src, edge_tgt, edge_name, enabled, fairness):
    """Search for a fair closed walk inside the reachable non-done subgraph.

    A closed walk is fair when, for every declared fairness action, either the
    walk uses an edge labelled with that action, or the walk satisfies the
    corresponding state condition (weak: some visited state has the action
    disabled; strong: every visited state has the action disabled).  The
    conditions only depend on the loop, so a counterexample is a closed walk.

    Returns (loop_edge_ids, loop_start_state) or None.
    """
    fair_names = [item["action"] for item in fairness]
    fair_mode = {item["action"]: item["mode"] for item in fairness}
    disabled = {}
    for name in fair_names:
        dis = enabled.get(name)
        disabled[name] = set(reach) - dis if dis else set(reach)
    radj = {}
    for v in reach:
        radj[v] = [(eid, w) for (eid, w) in adj_all[v] if w in reach]
    comp_of, comps = tarjan_scc(reach, radj)

    def region_edges(nodes):
        inside = []
        for v in nodes:
            for eid, w in radj[v]:
                if w in nodes:
                    inside.append(eid)
        return inside

    def solve(nodes):
        """Refine a strongly connected region until it is fair.

        Returns (region_nodes, internal_edge_ids) or None.
        """
        stack = [set(nodes)]
        while stack:
            region = stack.pop()
            inside = region_edges(region)
            if not inside:
                continue
            labels = set()
            for eid in inside:
                labels.add(edge_name[eid])
            uncovered = [nm for nm in fair_names if nm not in labels]
            shrink = None
            doomed = False
            for nm in uncovered:
                if fair_mode[nm] == "strong":
                    if not region <= disabled[nm]:
                        if shrink is None:
                            shrink = disabled[nm]
                        else:
                            shrink = shrink & disabled[nm]
                else:
                    if not (region & disabled[nm]):
                        doomed = True
                        break
            if doomed:
                continue
            if shrink is None:
                return region, inside
            reduced = region & shrink
            if not reduced:
                continue
            sub_adj = {}
            for v in reduced:
                sub_adj[v] = [(eid, w) for (eid, w) in radj[v] if w in reduced]
            sub_comp, sub_comps = tarjan_scc(reduced, sub_adj)
            for group in sub_comps:
                group_set = set(group)
                if not region_edges(group_set):
                    continue
                stack.append(group_set)
        return None

    for cid, nodes in enumerate(comps):
        result = solve(nodes)
        if result is not None:
            region, inside = result
            labels = {}
            for eid in inside:
                labels.setdefault(edge_name[eid], []).append(eid)
            req_edges = []
            for nm in fair_names:
                if nm in labels:
                    req_edges.append(labels[nm][0])
            visits = []
            for nm in fair_names:
                if nm not in labels:
                    for s in region:
                        if s in disabled[nm]:
                            visits.append(s)
                            break
            region_adj = {v: [] for v in region}
            for eid in inside:
                region_adj[edge_src[eid]].append((eid, edge_tgt[eid]))
            reg_comp, reg_comps = tarjan_scc(region, region_adj)
            reg_id = reg_comp[next(iter(region))]
            if req_edges:
                start_state = edge_src[req_edges[0]]
            else:
                start_state = next(iter(region))
            walk = []
            cur = start_state
            tasks = [("e", eid) for eid in req_edges]
            tasks.extend(("s", st) for st in visits)
            failed = False
            for tkind, tval in tasks:
                if tkind == "e":
                    seg = path_within(cur, edge_src[tval], region_adj, reg_comp, reg_id)
                    if seg is None:
                        failed = True
                        break
                    walk.extend(seg)
                    walk.append(tval)
                    cur = edge_tgt[tval]
                else:
                    seg = path_within(cur, tval, region_adj, reg_comp, reg_id)
                    if seg is None:
                        failed = True
                        break
                    walk.extend(seg)
                    cur = tval
            if failed:
                continue
            if not walk:
                only = inside[0]
                start_state = edge_src[only]
                walk.append(only)

